import{D as e,f as t,j as n,m as r,p as i,s as a,u as o}from"./runtime-core.esm-bundler-D3eD_xTR.js";import{t as s}from"./app-C_mnsEHS.js";var c=JSON.parse(`{"path":"/Linux/04_%E4%B8%89%E5%89%91%E5%AE%A2/02_sed%E6%B5%81%E7%BC%96%E8%BE%91%E5%99%A8.html","title":"sed 流编辑器","lang":"zh-CN","frontmatter":{"title":"sed 流编辑器","icon":"fa6-solid:file-lines","order":2,"category":["Linux三剑客"],"tag":["sed","流编辑器","模式空间","保持空间","文本替换"]},"git":{"createdTime":1780586585000,"updatedTime":1780586585000,"contributors":[{"name":"jackie.liu","username":"","email":"moklgy@foxmail.com","commits":1}]},"readingTime":{"minutes":21.22,"words":6365},"filePathRelative":"Linux/04_三剑客/02_sed流编辑器.md"}`),l={name:`02_sed流编辑器.md`};function u(s,c,l,u,d,f){let p=n(`Mermaid`);return e(),o(`div`,null,[c[0]||=t(`<h1 id="sed-流编辑器" tabindex="-1"><a class="header-anchor" href="#sed-流编辑器"><span>sed 流编辑器</span></a></h1><p>sed（Stream Editor）是 Unix 世界最经典的流编辑器，它逐行读取输入，在模式空间中对每行执行编辑命令，然后输出结果。与交互式编辑器不同，sed 天生适合批量文本变换——配置修改、数据清洗、日志格式化，一行命令即可处理百万行文本。</p><h2 id="_1-sed-工作原理" tabindex="-1"><a class="header-anchor" href="#_1-sed-工作原理"><span>1. sed 工作原理</span></a></h2><h3 id="_1-1-核心概念-两个缓冲区" tabindex="-1"><a class="header-anchor" href="#_1-1-核心概念-两个缓冲区"><span>1.1 核心概念：两个缓冲区</span></a></h3><p>sed 有两个关键缓冲区，理解它们是掌握 sed 的前提：</p><table><thead><tr><th>缓冲区</th><th>名称</th><th>作用</th><th>类比</th></tr></thead><tbody><tr><td><strong>Pattern Space</strong></td><td>模式空间</td><td>当前处理的行的工作台</td><td>手术台</td></tr><tr><td><strong>Hold Space</strong></td><td>保持空间</td><td>临时存储的暂存区</td><td>储物柜</td></tr></tbody></table>`,6),r(p,{code:``}),c[1]||=t(`<h3 id="_1-2-sed-执行流程详解" tabindex="-1"><a class="header-anchor" href="#_1-2-sed-执行流程详解"><span>1.2 sed 执行流程详解</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># sed 的完整执行流程：</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 1. 读取输入的一行到模式空间（覆盖之前内容）</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 2. 按顺序对所有匹配的地址执行命令</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 3. 除非用了 -n 选项，否则输出模式空间内容</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 4. 回到步骤1，处理下一行</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 5. 所有行处理完毕后退出</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 最简单的 sed——相当于 cat</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;&#39;</span><span style="color:#98C379;"> file</span><span style="color:#7F848E;font-style:italic;">                    # 每行读入，无操作，自动输出</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#D19A66;"> -n</span><span style="color:#98C379;"> &#39;p&#39;</span><span style="color:#98C379;"> file</span><span style="color:#7F848E;font-style:italic;">               # 每行读入，显式打印，效果同上</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_1-3-命令行语法" tabindex="-1"><a class="header-anchor" href="#_1-3-命令行语法"><span>1.3 命令行语法</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 基本语法</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#ABB2BF;"> [选项] </span><span style="color:#98C379;">&#39;命令&#39;</span><span style="color:#ABB2BF;"> 文件</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 多条命令（三种写法）</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;s/old/new/; s/foo/bar/&#39;</span><span style="color:#98C379;"> file</span><span style="color:#7F848E;font-style:italic;">              # 分号分隔</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#D19A66;"> -e</span><span style="color:#98C379;"> &#39;s/old/new/&#39;</span><span style="color:#D19A66;"> -e</span><span style="color:#98C379;"> &#39;s/foo/bar/&#39;</span><span style="color:#98C379;"> file</span><span style="color:#7F848E;font-style:italic;">       # 多个 -e</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;s/old/new/</span></span>
<span class="line"><span style="color:#98C379;">s/foo/bar/&#39;</span><span style="color:#98C379;"> file</span><span style="color:#7F848E;font-style:italic;">                                # 换行分隔（Shell中不常用）</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 从脚本文件读取</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#D19A66;"> -f</span><span style="color:#98C379;"> script.sed</span><span style="color:#98C379;"> file</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 就地修改（最常用的运维操作）</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#D19A66;"> -i</span><span style="color:#98C379;"> &#39;s/old/new/&#39;</span><span style="color:#98C379;"> file</span><span style="color:#7F848E;font-style:italic;">                        # 直接修改文件</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#D19A66;"> -i.bak</span><span style="color:#98C379;"> &#39;s/old/new/&#39;</span><span style="color:#98C379;"> file</span><span style="color:#7F848E;font-style:italic;">                    # 修改并备份原文件为 file.bak</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container warning"><p class="hint-container-title">-i 的安全隐患</p><p><code>sed -i</code> 会直接覆盖原文件，没有确认步骤。建议：</p><ol><li>先不加 <code>-i</code> 测试输出是否正确</li><li>使用 <code>sed -i.bak</code> 自动备份</li><li>对重要文件先 <code>cp file file.bak</code> 再操作</li></ol></div><h2 id="_2-地址定址" tabindex="-1"><a class="header-anchor" href="#_2-地址定址"><span>2. 地址定址</span></a></h2><p>sed 命令可以指定在哪些行上执行——这就是&quot;地址定址&quot;。没有地址的命令作用于所有行。</p><h3 id="_2-1-地址类型一览" tabindex="-1"><a class="header-anchor" href="#_2-1-地址类型一览"><span>2.1 地址类型一览</span></a></h3><table><thead><tr><th>地址类型</th><th>语法</th><th>示例</th><th>含义</th></tr></thead><tbody><tr><td>无地址</td><td><code>cmd</code></td><td><code>p</code></td><td>所有行</td></tr><tr><td>单行号</td><td><code>Ncmd</code></td><td><code>3p</code></td><td>第 3 行</td></tr><tr><td>最后一行</td><td><code>$cmd</code></td><td><code>$p</code></td><td>最后一行</td></tr><tr><td>正则匹配</td><td><code>/pat/cmd</code></td><td><code>/error/p</code></td><td>匹配 pattern 的行</td></tr><tr><td>行号范围</td><td><code>N,Mcmd</code></td><td><code>5,10p</code></td><td>第 5 到 10 行</td></tr><tr><td>正则范围</td><td><code>/pat1/,/pat2/cmd</code></td><td><code>/start/,/end/p</code></td><td>从匹配 pat1 到匹配 pat2</td></tr><tr><td>步长</td><td><code>N~Mcmd</code></td><td><code>1~2p</code></td><td>从第 N 行开始每隔 M 行</td></tr><tr><td>取反</td><td><code>addr!cmd</code></td><td><code>5!p</code></td><td>不匹配地址的行</td></tr></tbody></table><h3 id="_2-2-行号定址" tabindex="-1"><a class="header-anchor" href="#_2-2-行号定址"><span>2.2 行号定址</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 打印第 5 行</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#D19A66;"> -n</span><span style="color:#98C379;"> &#39;5p&#39;</span><span style="color:#98C379;"> file</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 打印第 5 到 10 行</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#D19A66;"> -n</span><span style="color:#98C379;"> &#39;5,10p&#39;</span><span style="color:#98C379;"> file</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 打印最后一行</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#D19A66;"> -n</span><span style="color:#98C379;"> &#39;$p&#39;</span><span style="color:#98C379;"> file</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 打印第 1 到最后一行（即全部）</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#D19A66;"> -n</span><span style="color:#98C379;"> &#39;1,$p&#39;</span><span style="color:#98C379;"> file</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 删除第 3 行</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;3d&#39;</span><span style="color:#98C379;"> file</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 删除第 10 到最后一行</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;10,$d&#39;</span><span style="color:#98C379;"> file</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 步长：打印奇数行</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#D19A66;"> -n</span><span style="color:#98C379;"> &#39;1~2p&#39;</span><span style="color:#98C379;"> file</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 步长：打印偶数行</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#D19A66;"> -n</span><span style="color:#98C379;"> &#39;0~2p&#39;</span><span style="color:#98C379;"> file</span><span style="color:#7F848E;font-style:italic;">           # GNU sed</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#D19A66;"> -n</span><span style="color:#98C379;"> &#39;2~2p&#39;</span><span style="color:#98C379;"> file</span><span style="color:#7F848E;font-style:italic;">           # 更通用</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_2-3-正则定址" tabindex="-1"><a class="header-anchor" href="#_2-3-正则定址"><span>2.3 正则定址</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 打印包含 error 的行</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#D19A66;"> -n</span><span style="color:#98C379;"> &#39;/error/p&#39;</span><span style="color:#98C379;"> file</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 删除空行</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;/^$/d&#39;</span><span style="color:#98C379;"> file</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 删除注释行（# 开头）</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;/^#/d&#39;</span><span style="color:#98C379;"> file</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 删除空行和注释行</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;/^$/d; /^#/d&#39;</span><span style="color:#98C379;"> file</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#D19A66;"> -e</span><span style="color:#98C379;"> &#39;/^$/d&#39;</span><span style="color:#D19A66;"> -e</span><span style="color:#98C379;"> &#39;/^#/d&#39;</span><span style="color:#98C379;"> file</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 打印从 START 到 END 之间的行</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#D19A66;"> -n</span><span style="color:#98C379;"> &#39;/START/,/END/p&#39;</span><span style="color:#98C379;"> file</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 修改从 &lt;VirtualHost&gt; 到 &lt;/VirtualHost&gt; 之间的内容</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;/&lt;VirtualHost/,/&lt;\\/VirtualHost/ s/80/8080/&#39;</span><span style="color:#98C379;"> httpd.conf</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 正则定址中的正则修饰符</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#D19A66;"> -n</span><span style="color:#98C379;"> &#39;/error/Ip&#39;</span><span style="color:#98C379;"> file</span><span style="color:#7F848E;font-style:italic;">       # I 标志：忽略大小写</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container important"><p class="hint-container-title">正则范围的特殊行为</p><p>当第一个模式匹配后，sed 会一直匹配到第二个模式为止。如果文件结束仍未匹配第二个模式，则从第一个模式匹配行到文件末尾都会被选中。如果再次出现第一个模式，会开始新的范围。</p></div><h3 id="_2-4-取反定址" tabindex="-1"><a class="header-anchor" href="#_2-4-取反定址"><span>2.4 取反定址</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 删除除第 5 行外的所有行（即只保留第 5 行）</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;5!d&#39;</span><span style="color:#98C379;"> file</span><span style="color:#7F848E;font-style:italic;">                # 等同于 sed -n &#39;5p&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 删除不包含 error 的行（即只保留包含 error 的行）</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;/error/!d&#39;</span><span style="color:#98C379;"> file</span><span style="color:#7F848E;font-style:italic;">          # 等同于 sed -n &#39;/error/p&#39; 或 grep &#39;error&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 对非注释行执行替换</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;/^#/!s/old/new/&#39;</span><span style="color:#98C379;"> file</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 对非空行添加行号</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;/^$/!=&#39;</span><span style="color:#98C379;"> file</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_3-常用命令详解" tabindex="-1"><a class="header-anchor" href="#_3-常用命令详解"><span>3. 常用命令详解</span></a></h2><h3 id="_3-1-命令速查表" tabindex="-1"><a class="header-anchor" href="#_3-1-命令速查表"><span>3.1 命令速查表</span></a></h3><table><thead><tr><th>命令</th><th>全称</th><th>作用</th><th>模式空间影响</th></tr></thead><tbody><tr><td><code>s</code></td><td>substitute</td><td>替换</td><td>修改内容</td></tr><tr><td><code>d</code></td><td>delete</td><td>删除行</td><td>清空模式空间</td></tr><tr><td><code>p</code></td><td>print</td><td>打印行</td><td>不变</td></tr><tr><td><code>a</code></td><td>append</td><td>在行后追加</td><td>不变（追加到输出）</td></tr><tr><td><code>i</code></td><td>insert</td><td>在行前插入</td><td>不变（插入到输出）</td></tr><tr><td><code>c</code></td><td>change</td><td>替换整行</td><td>替换内容</td></tr><tr><td><code>n</code></td><td>next</td><td>读取下一行</td><td>覆盖模式空间</td></tr><tr><td><code>N</code></td><td>Next</td><td>追加下一行</td><td>追加到模式空间</td></tr><tr><td><code>D</code></td><td>Delete</td><td>删除模式空间第一行</td><td>删除至第一个换行符</td></tr><tr><td><code>P</code></td><td>Print</td><td>打印模式空间第一行</td><td>不变</td></tr><tr><td><code>h</code></td><td>hold</td><td>覆盖保持空间</td><td>不变</td></tr><tr><td><code>H</code></td><td>Hold</td><td>追加到保持空间</td><td>不变</td></tr><tr><td><code>g</code></td><td>get</td><td>从保持空间覆盖</td><td>被覆盖</td></tr><tr><td><code>G</code></td><td>Get</td><td>从保持空间追加</td><td>追加换行+内容</td></tr><tr><td><code>x</code></td><td>exchange</td><td>交换两个空间</td><td>互换</td></tr><tr><td><code>=</code></td><td>line number</td><td>打印行号</td><td>不变</td></tr><tr><td><code>q</code></td><td>quit</td><td>退出 sed</td><td>不变</td></tr><tr><td><code>r</code></td><td>read</td><td>读取文件内容追加</td><td>不变</td></tr><tr><td><code>w</code></td><td>write</td><td>写入文件</td><td>不变</td></tr><tr><td><code>y</code></td><td>transliterate</td><td>字符转换（类似 tr）</td><td>修改内容</td></tr><tr><td><code>l</code></td><td>look</td><td>不可见字符可视化</td><td>不变</td></tr></tbody></table><h3 id="_3-2-替换命令-s——最核心的命令" tabindex="-1"><a class="header-anchor" href="#_3-2-替换命令-s——最核心的命令"><span>3.2 替换命令 s——最核心的命令</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 基本语法：s/模式/替换/标志</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 基本替换</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;s/old/new/&#39;</span><span style="color:#98C379;"> file</span><span style="color:#7F848E;font-style:italic;">                  # 每行替换第一个</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;s/old/new/g&#39;</span><span style="color:#98C379;"> file</span><span style="color:#7F848E;font-style:italic;">                 # 替换所有（global）</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;s/old/new/2&#39;</span><span style="color:#98C379;"> file</span><span style="color:#7F848E;font-style:italic;">                 # 只替换每行第 2 个</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;s/old/new/2g&#39;</span><span style="color:#98C379;"> file</span><span style="color:#7F848E;font-style:italic;">                # 从第 2 个开始替换所有</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 替换标志</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># g  - 全局替换</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># i/I - 忽略大小写</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># p  - 打印替换后的行（常配合 -n 使用）</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># w file - 将替换结果写入文件</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 只打印发生替换的行</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#D19A66;"> -n</span><span style="color:#98C379;"> &#39;s/error/ERROR/p&#39;</span><span style="color:#98C379;"> file</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 替换并写入新文件</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;s/old/new/gw output.txt&#39;</span><span style="color:#98C379;"> file</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 忽略大小写替换</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;s/error/ERROR/gi&#39;</span><span style="color:#98C379;"> file</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h4 id="替换中的特殊字符" tabindex="-1"><a class="header-anchor" href="#替换中的特殊字符"><span>替换中的特殊字符</span></a></h4><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># &amp; ——代表整个匹配内容</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;s/[0-9]\\+/[&amp;]/&#39;</span><span style="color:#98C379;"> file</span><span style="color:#7F848E;font-style:italic;">              # 给数字加方括号</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 123 → [123]</span></span>
<span class="line"><span style="color:#56B6C2;">echo</span><span style="color:#98C379;"> &#39;hello world&#39;</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;s/\\w\\+/[&amp;]/g&#39;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># [hello] [world]</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># \\1, \\2... ——反向引用分组</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;s/\\([a-z]\\+\\) \\([a-z]\\+\\)/\\2 \\1/&#39;</span><span style="color:#98C379;"> file</span><span style="color:#7F848E;font-style:italic;">    # 交换两个单词</span></span>
<span class="line"><span style="color:#56B6C2;">echo</span><span style="color:#98C379;"> &#39;hello world&#39;</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;s/\\(hello\\) \\(world\\)/\\2 \\1/&#39;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># world hello</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 使用 ERE 减少反斜杠</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#D19A66;"> -E</span><span style="color:#98C379;"> &#39;s/([a-z]+) ([a-z]+)/\\2 \\1/&#39;</span><span style="color:#98C379;"> file</span><span style="color:#7F848E;font-style:italic;">        # 同上，更清晰</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 替换分隔符可以更换（处理路径时极有用）</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 用 / 作分隔符——噩梦</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;s/\\/usr\\/local\\/bin/\\/opt\\/bin/&#39;</span><span style="color:#98C379;"> file</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 用 # 或 | 作分隔符——清晰</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;s#/usr/local/bin#/opt/bin#&#39;</span><span style="color:#98C379;"> file</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;s|/usr/local/bin|/opt/bin|&#39;</span><span style="color:#98C379;"> file</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 部分删除（替换为空）</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;s/[[:space:]]*$//&#39;</span><span style="color:#98C379;"> file</span><span style="color:#7F848E;font-style:italic;">           # 删除行尾空格</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;s/^[[:space:]]*//&#39;</span><span style="color:#98C379;"> file</span><span style="color:#7F848E;font-style:italic;">           # 删除行首空格</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;s/&lt;[^&gt;]*&gt;//g&#39;</span><span style="color:#98C379;"> html.txt</span><span style="color:#7F848E;font-style:italic;">            # 删除 HTML 标签</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container tip"><p class="hint-container-title">分隔符选择原则</p><ol><li>默认用 <code>/</code></li><li>当模式或替换中包含 <code>/</code> 时，换用 <code>#</code>、<code>|</code>、<code>@</code>、<code>!</code> 等</li><li>选择模式中最不常出现的字符作为分隔符</li></ol></div><h3 id="_3-3-追加、插入、修改" tabindex="-1"><a class="header-anchor" href="#_3-3-追加、插入、修改"><span>3.3 追加、插入、修改</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># a（append）——在匹配行后追加</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;/error/a\\=== ERROR FOUND ===&#39;</span><span style="color:#98C379;"> file</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># error line</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># === ERROR FOUND ===</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 追加多行</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;/error/a\\=== ERROR FOUND ===\\</span></span>
<span class="line"><span style="color:#98C379;">Please check the log&#39;</span><span style="color:#98C379;"> file</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># i（insert）——在匹配行前插入</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;/ServerName/i\\# Added by admin&#39;</span><span style="color:#98C379;"> httpd.conf</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># # Added by admin</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># ServerName example.com</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># c（change）——替换整行</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;/^Port/c\\Port 2222&#39;</span><span style="color:#98C379;"> sshd_config</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 将 Port 开头的行替换为 Port 2222</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 在文件开头添加内容</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;1i\\#!/bin/bash\\n# Auto-generated script&#39;</span><span style="color:#98C379;"> script.sh</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 在文件末尾追加</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;$a\\# End of configuration&#39;</span><span style="color:#98C379;"> config.conf</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-4-删除命令" tabindex="-1"><a class="header-anchor" href="#_3-4-删除命令"><span>3.4 删除命令</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 删除空行</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;/^$/d&#39;</span><span style="color:#98C379;"> file</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 删除行首空格（不删除行）</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;s/^[[:space:]]*//&#39;</span><span style="color:#98C379;"> file</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 删除行尾空格</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;s/[[:space:]]*$//&#39;</span><span style="color:#98C379;"> file</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 删除注释行</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;/^#/d&#39;</span><span style="color:#98C379;"> file</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 删除 C 风格注释 /* ... */（单行）</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;/\\/\\*.*\\*\\//d&#39;</span><span style="color:#98C379;"> file</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 删除 HTML 标签</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;s/&lt;[^&gt;]*&gt;//g&#39;</span><span style="color:#98C379;"> file</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 删除第 1 到 5 行</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;1,5d&#39;</span><span style="color:#98C379;"> file</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 删除从 pattern 到文件末尾</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;/pattern/,$d&#39;</span><span style="color:#98C379;"> file</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-5-打印与行号" tabindex="-1"><a class="header-anchor" href="#_3-5-打印与行号"><span>3.5 打印与行号</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># p 命令——打印（通常配合 -n 使用，否则会输出两遍）</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#D19A66;"> -n</span><span style="color:#98C379;"> &#39;5,10p&#39;</span><span style="color:#98C379;"> file</span><span style="color:#7F848E;font-style:italic;">              # 打印第 5-10 行（等同于 head -10 | tail -6）</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#D19A66;"> -n</span><span style="color:#98C379;"> &#39;/error/p&#39;</span><span style="color:#98C379;"> file</span><span style="color:#7F848E;font-style:italic;">           # 打印包含 error 的行（等同于 grep）</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 等号命令——打印行号</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#D19A66;"> -n</span><span style="color:#98C379;"> &#39;/error/=&#39;</span><span style="color:#98C379;"> file</span><span style="color:#7F848E;font-style:italic;">           # 只打印行号</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#D19A66;"> -n</span><span style="color:#98C379;"> &#39;/error/{=;p}&#39;</span><span style="color:#98C379;"> file</span><span style="color:#7F848E;font-style:italic;">       # 打印行号和内容</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 巧妙实现 cat -n（加行号）</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;=&#39;</span><span style="color:#98C379;"> file</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;N;s/\\n/\\t/&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 只打印匹配行的行号和内容</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#D19A66;"> -n</span><span style="color:#98C379;"> &#39;/pattern/{=;p}&#39;</span><span style="color:#98C379;"> file</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;N;s/\\n/: /&#39;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-6-退出与读取" tabindex="-1"><a class="header-anchor" href="#_3-6-退出与读取"><span>3.6 退出与读取</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># q——读取到指定行后退出</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;5q&#39;</span><span style="color:#98C379;"> file</span><span style="color:#7F848E;font-style:italic;">                    # 等同于 head -5</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;/^EOF$/q&#39;</span><span style="color:#98C379;"> file</span><span style="color:#7F848E;font-style:italic;">              # 读到 EOF 行后停止</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 打印文件前 10 行（比 head 高效——不会继续读取）</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;10q&#39;</span><span style="color:#98C379;"> file</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># r——读取文件内容追加到匹配行后</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;/&lt;body&gt;/r header.html&#39;</span><span style="color:#98C379;"> page.html</span><span style="color:#7F848E;font-style:italic;">    # 在 &lt;body&gt; 后插入 header.html</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 合并文件</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;$r file2.txt&#39;</span><span style="color:#98C379;"> file1.txt</span><span style="color:#7F848E;font-style:italic;">     # 在 file1 末尾追加 file2 的内容</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># w——将匹配行写入文件</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#D19A66;"> -n</span><span style="color:#98C379;"> &#39;/error/w errors.txt&#39;</span><span style="color:#98C379;"> app.log</span><span style="color:#7F848E;font-style:italic;">     # 将错误行写入 errors.txt</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;/^#/w comments.txt&#39;</span><span style="color:#98C379;"> config.conf</span><span style="color:#7F848E;font-style:italic;">     # 注释行写入单独文件</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-7-字符转换-y" tabindex="-1"><a class="header-anchor" href="#_3-7-字符转换-y"><span>3.7 字符转换 y</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># y 命令——逐字符转换（类似 tr）</span></span>
<span class="line"><span style="color:#56B6C2;">echo</span><span style="color:#98C379;"> &#39;Hello World&#39;</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;y/abcdefghijklmnopqrstuvwxyz/ABCDEFGHIJKLMNOPQRSTUVWXYZ/&#39;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># HELLO WORLD</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 更实用的场景——大小写转换</span></span>
<span class="line"><span style="color:#56B6C2;">echo</span><span style="color:#98C379;"> &#39;hello&#39;</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;y/a-z/A-Z/&#39;</span><span style="color:#7F848E;font-style:italic;">         # GNU sed 扩展</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 实际上这个不工作！y 命令不支持范围，必须列出每个字符</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 正确做法</span></span>
<span class="line"><span style="color:#56B6C2;">echo</span><span style="color:#98C379;"> &#39;hello&#39;</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;y/abcdefghijklmnopqrstuvwxyz/ABCDEFGHIJKLMNOPQRSTUVWXYZ/&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 或者用更简单的方法</span></span>
<span class="line"><span style="color:#56B6C2;">echo</span><span style="color:#98C379;"> &#39;hello&#39;</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;s/.*/\\U&amp;/&#39;</span><span style="color:#7F848E;font-style:italic;">          # GNU sed 扩展</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_4-多行处理" tabindex="-1"><a class="header-anchor" href="#_4-多行处理"><span>4. 多行处理</span></a></h2><p>多行处理是 sed 最强大也最复杂的部分，它打破了&quot;逐行处理&quot;的局限。</p><h3 id="_4-1-n-d-p-命令详解" tabindex="-1"><a class="header-anchor" href="#_4-1-n-d-p-命令详解"><span>4.1 N/D/P 命令详解</span></a></h3>`,37),r(p,{code:``}),c[2]||=t(`<div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># N 命令——追加下一行到模式空间</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 场景：合并被换行拆分的行（如 &quot;abc\\\\\\n&quot; 续行）</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;/\\\\$/{N;s/\\\\\\n//;}&#39;</span><span style="color:#98C379;"> file</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 输入：</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">#   first line\\</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">#   second line</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 输出：</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">#   first linesecond line</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># D 命令——删除模式空间第一行</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 场景：删除连续的空行，只保留一个</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;/^$/{N;/^\\n$/d;}&#39;</span><span style="color:#98C379;"> file</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># P 命令——打印模式空间第一行</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 场景：只打印多行模式空间的第一行</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#D19A66;"> -n</span><span style="color:#98C379;"> &#39;N;P&#39;</span><span style="color:#98C379;"> file</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_4-2-合并相邻行" tabindex="-1"><a class="header-anchor" href="#_4-2-合并相邻行"><span>4.2 合并相邻行</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 将每两行合并为一行</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;N;s/\\n/ /&#39;</span><span style="color:#98C379;"> file</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 输入：</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">#   line1</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">#   line2</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">#   line3</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">#   line4</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 输出：</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">#   line1 line2</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">#   line3 line4</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 将所有行合并为一行</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;:a;N;$!ba;s/\\n/ /g&#39;</span><span style="color:#98C379;"> file</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 解释：</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># :a       设置标签 a</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># N        追加下一行</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># $!ba     如果不是最后一行，跳转到标签 a</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># s/\\n/ /g 替换所有换行为空格</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 合并以特定字符结尾的行（如反斜杠续行）</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;:a;/\\\\$/{N;ba;}&#39;</span><span style="color:#98C379;"> file</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;s/\\\\\\n//g&#39;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 输入：</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">#   CFLAGS=-O2 \\</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">#   -Wall \\</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">#   -Werror</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 输出：</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">#   CFLAGS=-O2 -Wall -Werror</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_4-3-删除连续空行" tabindex="-1"><a class="header-anchor" href="#_4-3-删除连续空行"><span>4.3 删除连续空行</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 删除连续空行，只保留一个空行</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;/^$/N;/^\\n$/d&#39;</span><span style="color:#98C379;"> file</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 工作原理：</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 1. 遇到空行</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 2. N 追加下一行</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 3. 如果下一行也是空（^\\n$），删除整个模式空间</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 4. 否则正常输出</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 删除所有空行</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;/^$/d&#39;</span><span style="color:#98C379;"> file</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 删除开头空行</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;/./,$!d&#39;</span><span style="color:#98C379;"> file</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 删除结尾空行</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#D19A66;"> -e</span><span style="color:#98C379;"> :a</span><span style="color:#D19A66;"> -e</span><span style="color:#98C379;"> &#39;/^\\n*$/{$d;N;ba;}&#39;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_4-4-反转行序" tabindex="-1"><a class="header-anchor" href="#_4-4-反转行序"><span>4.4 反转行序</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 反转文件所有行（类似 tac）</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;1!G;h;$!d&#39;</span><span style="color:#98C379;"> file</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 工作原理：</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 第1行：1!G 不执行 → h 存入保持空间 → $!d 删除模式空间（不输出）</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 第2行：1!G 将保持空间(第1行)追加到模式空间(第2行) → h 存入保持空间 → $!d 删除</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 第3行：1!G 追加(第1行\\n第2行) → h → 最后一行！不删除，输出</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 输出：第3行\\n第2行\\n第1行</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 更易理解的写法</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#D19A66;"> -n</span><span style="color:#98C379;"> &#39;1!G;h;$p&#39;</span><span style="color:#98C379;"> file</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container important"><p class="hint-container-title">理解 1!G;h;$!d</p><p>这是 sed 最经典的&quot;黑魔法&quot;之一，拆解如下：</p><ol><li><code>1!G</code> ——非第1行时，将保持空间追加到模式空间</li><li><code>h</code> ——将模式空间覆盖到保持空间（不断累积反转后的内容）</li><li><code>$!d</code> ——非最后一行时，删除模式空间（不输出）</li><li>到最后一行时，<code>$!d</code> 不执行，模式空间（已反转）自动输出</li></ol></div><h2 id="_5-保持空间操作" tabindex="-1"><a class="header-anchor" href="#_5-保持空间操作"><span>5. 保持空间操作</span></a></h2><h3 id="_5-1-保持空间命令交互图" tabindex="-1"><a class="header-anchor" href="#_5-1-保持空间命令交互图"><span>5.1 保持空间命令交互图</span></a></h3>`,10),r(p,{code:`eJxLy8kvT85ILCpR8AniUgCCgOBopWcrFj7d0/985a6X07fE5L3f0/F0+9Ine+c87d/wfk+nUqyCrq5djVIGUPzFsrbns6eBBGsUPIAan+yf+6ynEUnjs1lNT9fOeNqzC6wRagFEvwdI//69T7sWwPSDpT2g0uloxgegSruj6YZKAw230dUDKagAKniya8mz3kVw48Eqiksqc1JB6tIyc3KslFMN00zTUnWKS4rys1OtlA2MzM2TUpAUAu2DKEwzTjVNM4UrNE8yTEs04gIAEsGJQw==`}),c[3]||=t(`<h3 id="_5-2-保持空间实战" tabindex="-1"><a class="header-anchor" href="#_5-2-保持空间实战"><span>5.2 保持空间实战</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 案例1：将匹配行移到文件末尾</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;/pattern/{H;d;};$G&#39;</span><span style="color:#98C379;"> file</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># H 追加到保持空间 → d 删除该行 → $G 在末尾追加保持空间内容</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 案例2：将匹配行移到文件开头</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;/pattern/{h;d;};G&#39;</span><span style="color:#98C379;"> file</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># h 存入保持空间 → d 删除 → G 追加到每行之后</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 注意：这会在每行后追加，不太对。正确写法：</span></span>
<span class="line"></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#D19A66;"> -e</span><span style="color:#98C379;"> &#39;/pattern/{H;d;}&#39;</span><span style="color:#D19A66;"> -e</span><span style="color:#98C379;"> &#39;\${x;G;}&#39;</span><span style="color:#98C379;"> file</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># H 收集所有匹配行到保持空间 → d 删除 → 最后一行时 x 取出保持空间 → G 追加</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 案例3：双行合一（将下一行内容追加到当前行末尾）</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;N;s/\\n/ /&#39;</span><span style="color:#98C379;"> file</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 案例4：行列转换（每行一个单词 → 一行逗号分隔）</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;:a;N;$!ba;s/\\n/,/g&#39;</span><span style="color:#98C379;"> file</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># word1</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># word2</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># word3 → word1,word2,word3</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 案例5：给文件添加标题行</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;1h;1d;2{x;G;}&#39;</span><span style="color:#98C379;"> file</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 不太对，正确写法：</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;1{i\\</span></span>
<span class="line"><span style="color:#98C379;"># Title Header</span></span>
<span class="line"><span style="color:#98C379;">}&#39;</span><span style="color:#98C379;"> file</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 案例6：交换相邻行</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;{N;s/\\(.*\\)\\n\\(.*\\)/\\2\\n\\1/}&#39;</span><span style="color:#98C379;"> file</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># line1      line2</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># line2  →   line1</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># line3      line4</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># line4      line3</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_5-3-模式空间与保持空间协作流程" tabindex="-1"><a class="header-anchor" href="#_5-3-模式空间与保持空间协作流程"><span>5.3 模式空间与保持空间协作流程</span></a></h3>`,3),r(p,{code:``}),c[4]||=t(`<h2 id="_6-分支与测试" tabindex="-1"><a class="header-anchor" href="#_6-分支与测试"><span>6. 分支与测试</span></a></h2><h3 id="_6-1-标签与跳转" tabindex="-1"><a class="header-anchor" href="#_6-1-标签与跳转"><span>6.1 标签与跳转</span></a></h3><table><thead><tr><th>命令</th><th>语法</th><th>作用</th></tr></thead><tbody><tr><td><code>:label</code></td><td><code>:a</code></td><td>定义标签</td></tr><tr><td><code>b label</code></td><td><code>b a</code></td><td>无条件跳转到标签</td></tr><tr><td><code>t label</code></td><td><code>t a</code></td><td>如果最近一次替换成功，跳转到标签</td></tr></tbody></table><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># b 命令——无条件跳转</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 删除所有前导空格（循环替换）</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;:a;s/^[[:space:]]//;ta&#39;</span><span style="color:#98C379;"> file</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># :a       定义标签 a</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># s/^...// 替换行首空格</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># ta       如果替换成功，跳回标签 a（循环直到没有前导空格）</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 给数字加千分位分隔符</span></span>
<span class="line"><span style="color:#56B6C2;">echo</span><span style="color:#98C379;"> &#39;1234567890&#39;</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;:a;s/\\B[0-9]\\{3\\}\\&gt;/,&amp;/;ta&#39;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 1,234,567,890</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 工作原理：从右向左，每3位数字前加逗号</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># \\B 非词边界（确保不是开头）</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># ta 替换成功则循环</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 使用 ERE 更清晰</span></span>
<span class="line"><span style="color:#56B6C2;">echo</span><span style="color:#98C379;"> &#39;1234567890&#39;</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">sed</span><span style="color:#D19A66;"> -E</span><span style="color:#98C379;"> &#39;:a;s/([0-9])([0-9]{3})($|[^0-9])/\\1,\\2\\3/;ta&#39;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_6-2-条件分支-t" tabindex="-1"><a class="header-anchor" href="#_6-2-条件分支-t"><span>6.2 条件分支 t</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># t 命令——替换成功则跳转</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 去除嵌套引号</span></span>
<span class="line"><span style="color:#56B6C2;">echo</span><span style="color:#98C379;"> &#39;&quot;&quot;hello&quot;&quot;&#39;</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;:a;s/&quot;&quot;/&quot;/;ta&#39;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># &quot;hello&quot;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 每次替换一对引号，成功则循环</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 递归替换</span></span>
<span class="line"><span style="color:#56B6C2;">echo</span><span style="color:#98C379;"> &#39;aabbcc&#39;</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;:a;s/\\([a-z]\\)\\1/\\1/;ta&#39;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># abc</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 将连续重复字母合并为一个</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 只在替换成功时执行额外操作</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;s/error/ERROR/;t;s/warn/WARN/&#39;</span><span style="color:#98C379;"> file</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 如果 error→ERROR 成功，跳过 warn→WARN</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 如果 error→ERROR 失败，尝试 warn→WARN</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_6-3-分支与保持空间组合" tabindex="-1"><a class="header-anchor" href="#_6-3-分支与保持空间组合"><span>6.3 分支与保持空间组合</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 将所有匹配行收集到文件末尾</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#D19A66;"> -n</span><span style="color:#98C379;"> &#39;/pattern/{H;d;};p;\${x;p;}&#39;</span><span style="color:#98C379;"> file</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># /pattern/ 匹配行 → H 追加到保持空间 → d 删除不输出</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 非匹配行 → p 正常输出</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 最后一行 → x 取出保持空间 → p 输出</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 交替合并两个文件的内容</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># file1: a, b, c</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># file2: 1, 2, 3</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 结果: a, 1, b, 2, c, 3</span></span>
<span class="line"><span style="color:#61AFEF;">paste</span><span style="color:#D19A66;"> -d</span><span style="color:#98C379;">&#39;\\n&#39;</span><span style="color:#98C379;"> file1</span><span style="color:#98C379;"> file2</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 用 sed 实现类似的合并</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;R file2&#39;</span><span style="color:#98C379;"> file1</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># R 命令在每行后读取 file2 的下一行追加</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_7-sed-脚本文件" tabindex="-1"><a class="header-anchor" href="#_7-sed-脚本文件"><span>7. sed 脚本文件</span></a></h2><h3 id="_7-1-编写脚本文件" tabindex="-1"><a class="header-anchor" href="#_7-1-编写脚本文件"><span>7.1 编写脚本文件</span></a></h3><p>当 sed 命令变得复杂时，写成脚本文件更易于维护。</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># script.sed —— 配置文件标准化脚本</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">#!/usr/bin/sed -f</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 删除空行和注释行</span></span>
<span class="line"><span style="color:#61AFEF;">/^$/d</span></span>
<span class="line"><span style="color:#61AFEF;">/^#/d</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 删除行尾空格</span></span>
<span class="line"><span style="color:#61AFEF;">s/[[:space:]]*$//</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 统一缩进为 4 个空格</span></span>
<span class="line"><span style="color:#61AFEF;">s/^\\t/</span><span style="color:#98C379;">    /g</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 替换旧域名</span></span>
<span class="line"><span style="color:#61AFEF;">s/old\\.example\\.com/new.example.com/g</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 在 ServerName 前添加注释</span></span>
<span class="line"><span style="color:#61AFEF;">/ServerName/i\\#</span><span style="color:#98C379;"> Updated</span><span style="color:#98C379;"> by</span><span style="color:#98C379;"> automation</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 在文件末尾追加配置</span></span>
<span class="line"><span style="color:#E06C75;">$a</span><span style="color:#56B6C2;">\\</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># Added by automation\\</span></span>
<span class="line"><span style="color:#61AFEF;">Timeout</span><span style="color:#D19A66;"> 300</span><span style="color:#56B6C2;">\\</span></span>
<span class="line"><span style="color:#ABB2BF;">KeepAlive </span><span style="color:#98C379;">On</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 使用脚本文件</span></span>
<span class="line"><span style="color:#61AFEF;">chmod</span><span style="color:#98C379;"> +x</span><span style="color:#98C379;"> script.sed</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#D19A66;"> -f</span><span style="color:#98C379;"> script.sed</span><span style="color:#98C379;"> config.conf</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 或者直接执行</span></span>
<span class="line"><span style="color:#61AFEF;">./script.sed</span><span style="color:#98C379;"> config.conf</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_7-2-模块化脚本" tabindex="-1"><a class="header-anchor" href="#_7-2-模块化脚本"><span>7.2 模块化脚本</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># clean_log.sed —— 日志清洗脚本</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">#!/usr/bin/sed -f</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 阶段1：去除 ANSI 颜色码</span></span>
<span class="line"><span style="color:#61AFEF;">s/\\x1b\\[[0-9</span><span style="color:#ABB2BF;">;]*[mGKH]//g</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 阶段2：统一时间格式</span></span>
<span class="line"><span style="color:#61AFEF;">s/[0-9]\\</span><span style="color:#98C379;">{4</span><span style="color:#ABB2BF;">\\</span><span style="color:#98C379;">}</span><span style="color:#61AFEF;">\\/[0-9]\\</span><span style="color:#98C379;">{2</span><span style="color:#ABB2BF;">\\</span><span style="color:#98C379;">}</span><span style="color:#61AFEF;">\\/[0-9]\\</span><span style="color:#98C379;">{2</span><span style="color:#ABB2BF;">\\</span><span style="color:#98C379;">}</span><span style="color:#61AFEF;">/</span><span style="color:#ABB2BF;">&amp;</span><span style="color:#61AFEF;">/g</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 阶段3：去除行号前缀</span></span>
<span class="line"><span style="color:#61AFEF;">s/^[[:space:]]*[0-9]\\+[[:space:]]*//g</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 阶段4：删除空行</span></span>
<span class="line"><span style="color:#61AFEF;">/^$/d</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 阶段5：高亮错误</span></span>
<span class="line"><span style="color:#61AFEF;">s/ERROR/***</span><span style="color:#98C379;"> ERROR</span><span style="color:#E5C07B;"> ***</span><span style="color:#98C379;">/g</span></span>
<span class="line"><span style="color:#61AFEF;">s/FATAL/***</span><span style="color:#98C379;"> FATAL</span><span style="color:#E5C07B;"> ***</span><span style="color:#98C379;">/g</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_8-实战案例" tabindex="-1"><a class="header-anchor" href="#_8-实战案例"><span>8. 实战案例</span></a></h2><h3 id="_8-1-配置文件修改" tabindex="-1"><a class="header-anchor" href="#_8-1-配置文件修改"><span>8.1 配置文件修改</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 案例1：修改 SSH 端口</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#D19A66;"> -i</span><span style="color:#98C379;"> &#39;s/^Port .*/Port 2222/&#39;</span><span style="color:#98C379;"> /etc/ssh/sshd_config</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 案例2：启用 Nginx gzip</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#D19A66;"> -i</span><span style="color:#98C379;"> &#39;s/# gzip/gzip/&#39;</span><span style="color:#98C379;"> /etc/nginx/nginx.conf</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 案例3：修改 MySQL 绑定地址</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#D19A66;"> -i</span><span style="color:#98C379;"> &#39;s/^bind-address.*/bind-address = 0.0.0.0/&#39;</span><span style="color:#98C379;"> /etc/my.cnf</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 案例4：添加新配置项（如果不存在）</span></span>
<span class="line"><span style="color:#61AFEF;">grep</span><span style="color:#D19A66;"> -q</span><span style="color:#98C379;"> &#39;MaxKeepAliveRequests&#39;</span><span style="color:#98C379;"> httpd.conf</span><span style="color:#ABB2BF;"> || </span><span style="color:#56B6C2;">\\</span></span>
<span class="line"><span style="color:#61AFEF;">  sed</span><span style="color:#D19A66;"> -i</span><span style="color:#98C379;"> &#39;$a\\MaxKeepAliveRequests 1000&#39;</span><span style="color:#98C379;"> httpd.conf</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 案例5：修改指定段落的配置</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 在 [mysqld] 段下添加配置</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#D19A66;"> -i</span><span style="color:#98C379;"> &#39;/\\[mysqld\\]/a\\max_connections = 500&#39;</span><span style="color:#98C379;"> /etc/my.cnf</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 案例6：批量替换多个配置文件</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#D19A66;"> -i</span><span style="color:#98C379;"> &#39;s/server\\.old\\.com/server.new.com/g&#39;</span><span style="color:#98C379;"> /etc/nginx/sites-enabled/</span><span style="color:#E5C07B;">*</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 案例7：注释掉指定行</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#D19A66;"> -i</span><span style="color:#98C379;"> &#39;s/^PermitRootLogin.*/#&amp;/&#39;</span><span style="color:#98C379;"> /etc/ssh/sshd_config</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># PermitRootLogin yes → #PermitRootLogin yes</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 案例8：取消注释</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#D19A66;"> -i</span><span style="color:#98C379;"> &#39;s/^#\\(ServerName\\)/\\1/&#39;</span><span style="color:#98C379;"> /etc/apache2/httpd.conf</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container important"><p class="hint-container-title">配置修改的安全生产流程</p><ol><li><strong>先备份</strong>：<code>cp config.conf config.conf.bak</code> 或 <code>sed -i.bak</code></li><li><strong>先测试</strong>：不加 <code>-i</code> 先看输出</li><li><strong>用 -i.bak</strong>：自动备份原文件</li><li><strong>验证语法</strong>：修改后用工具检查（如 <code>nginx -t</code>、<code>apachectl configtest</code>）</li><li><strong>重启服务</strong>：修改生效</li></ol></div><h3 id="_8-2-数据清洗" tabindex="-1"><a class="header-anchor" href="#_8-2-数据清洗"><span>8.2 数据清洗</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 案例1：CSV 数据清洗</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 去除字段前后空格</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;s/ *,/,/g; s/, */,/g&#39;</span><span style="color:#98C379;"> data.csv</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 案例2：统一日期格式 MM/DD/YYYY → YYYY-MM-DD</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#D19A66;"> -E</span><span style="color:#98C379;"> &#39;s/([0-9]{2})\\/([0-9]{2})\\/([0-9]{4})/\\3-\\1-\\2/g&#39;</span><span style="color:#98C379;"> data.txt</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 案例3：去除 HTML 标签</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;s/&lt;[^&gt;]*&gt;//g&#39;</span><span style="color:#98C379;"> page.html</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 案例4：去除 Windows 换行符 \\r</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;s/\\r$//&#39;</span><span style="color:#98C379;"> file.txt</span><span style="color:#7F848E;font-style:italic;">                   # 删除 \\r</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#D19A66;"> -i</span><span style="color:#98C379;"> &#39;s/\\r$//&#39;</span><span style="color:#98C379;"> file.txt</span><span style="color:#7F848E;font-style:italic;">                # 就地修改</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 案例5：去除 ANSI 颜色码</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;s/\\x1b\\[[0-9;]*[mGKH]//g&#39;</span><span style="color:#98C379;"> colored_log.txt</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 案例6：去除行号</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;s/^[[:space:]]*[0-9]\\+[[:space:]]*//&#39;</span><span style="color:#98C379;"> numbered.txt</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 案例7：标准化空格（多个空格变一个）</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;s/[[:space:]]\\+/ /g&#39;</span><span style="color:#98C379;"> file</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 案例8：数字格式化（千分位）</span></span>
<span class="line"><span style="color:#56B6C2;">echo</span><span style="color:#98C379;"> &#39;1234567.89&#39;</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;:a;s/\\B[0-9]\\{3\\}\\&gt;/,&amp;/;ta&#39;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 1,234,567.89</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_8-3-批量替换" tabindex="-1"><a class="header-anchor" href="#_8-3-批量替换"><span>8.3 批量替换</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 案例1：全项目替换函数名</span></span>
<span class="line"><span style="color:#61AFEF;">find</span><span style="color:#98C379;"> .</span><span style="color:#D19A66;"> -name</span><span style="color:#98C379;"> &#39;*.py&#39;</span><span style="color:#D19A66;"> -exec</span><span style="color:#98C379;"> sed</span><span style="color:#D19A66;"> -i</span><span style="color:#98C379;"> &#39;s/old_function/new_function/g&#39;</span><span style="color:#98C379;"> {}</span><span style="color:#98C379;"> +</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 案例2：批量替换（带备份）</span></span>
<span class="line"><span style="color:#61AFEF;">find</span><span style="color:#98C379;"> .</span><span style="color:#D19A66;"> -name</span><span style="color:#98C379;"> &#39;*.conf&#39;</span><span style="color:#D19A66;"> -exec</span><span style="color:#98C379;"> sed</span><span style="color:#D19A66;"> -i.bak</span><span style="color:#98C379;"> &#39;s/old_host/new_host/g&#39;</span><span style="color:#98C379;"> {}</span><span style="color:#98C379;"> +</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 案例3：只替换特定目录下的文件</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#D19A66;"> -i</span><span style="color:#98C379;"> &#39;s/debug=True/debug=False/&#39;</span><span style="color:#98C379;"> src/</span><span style="color:#E5C07B;">**</span><span style="color:#98C379;">/</span><span style="color:#E5C07B;">*</span><span style="color:#98C379;">.py</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 案例4：替换但排除 .git 目录</span></span>
<span class="line"><span style="color:#61AFEF;">find</span><span style="color:#98C379;"> .</span><span style="color:#D19A66;"> -name</span><span style="color:#98C379;"> &#39;*.js&#39;</span><span style="color:#D19A66;"> -not</span><span style="color:#D19A66;"> -path</span><span style="color:#98C379;"> &#39;./.git/*&#39;</span><span style="color:#ABB2BF;"> | </span><span style="color:#56B6C2;">\\</span></span>
<span class="line"><span style="color:#61AFEF;">  xargs</span><span style="color:#98C379;"> sed</span><span style="color:#D19A66;"> -i</span><span style="color:#98C379;"> &#39;s/console\\.log/console.debug/g&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 案例5：替换并显示修改了哪些文件</span></span>
<span class="line"><span style="color:#61AFEF;">grep</span><span style="color:#D19A66;"> -rl</span><span style="color:#98C379;"> &#39;old_text&#39;</span><span style="color:#98C379;"> .</span><span style="color:#ABB2BF;"> | </span><span style="color:#C678DD;">while</span><span style="color:#56B6C2;"> read</span><span style="color:#98C379;"> f</span><span style="color:#ABB2BF;">; </span><span style="color:#C678DD;">do</span></span>
<span class="line"><span style="color:#61AFEF;">  sed</span><span style="color:#D19A66;"> -i</span><span style="color:#98C379;"> &#39;s/old_text/new_text/g&#39;</span><span style="color:#98C379;"> &quot;</span><span style="color:#E06C75;">$f</span><span style="color:#98C379;">&quot;</span></span>
<span class="line"><span style="color:#56B6C2;">  echo</span><span style="color:#98C379;"> &quot;Modified: </span><span style="color:#E06C75;">$f</span><span style="color:#98C379;">&quot;</span></span>
<span class="line"><span style="color:#C678DD;">done</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 案例6：条件替换——只替换包含特定上下文的行</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;/ServerName example/s/80/8080/&#39;</span><span style="color:#98C379;"> vhost.conf</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 只在包含 &quot;ServerName example&quot; 的行替换端口</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_8-4-文本格式化" tabindex="-1"><a class="header-anchor" href="#_8-4-文本格式化"><span>8.4 文本格式化</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 案例1：给代码添加行号</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;=&#39;</span><span style="color:#98C379;"> code.py</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;N;s/\\n/\\t/&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 案例2：将 Tab 转为空格</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;s/\\t/    /g&#39;</span><span style="color:#98C379;"> file</span><span style="color:#7F848E;font-style:italic;">          # 每个 Tab 替换为 4 空格</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 案例3：将空格转为 Tab</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;s/    /\\t/g&#39;</span><span style="color:#98C379;"> file</span><span style="color:#7F848E;font-style:italic;">          # 4 空格替换为 Tab</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 案例4：文本居中（假设 80 列宽）</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#D19A66;"> -e</span><span style="color:#98C379;"> &#39;:a&#39;</span><span style="color:#D19A66;"> -e</span><span style="color:#98C379;"> &#39;s/^.\\{1,78\\}$/ &amp;/;ta&#39;</span><span style="color:#98C379;"> file</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 不断在行首加空格，直到行宽达到 79</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 案例5：段落格式化——双换行分段</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;/^$/{N;s/\\n\\n/\\n\\n/;}&#39;</span><span style="color:#98C379;"> file</span><span style="color:#7F848E;font-style:italic;">   # 确保段落间只有一个空行</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 案例6：每行前加时间戳</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &quot;s/^/$(</span><span style="color:#61AFEF;">date</span><span style="color:#98C379;"> &#39;+%Y-%m-%d %H:%M:%S&#39;) /&quot;</span><span style="color:#98C379;"> file</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 案例7：截断过长行</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;s/\\(.\\{80\\}\\).*/\\1/&#39;</span><span style="color:#98C379;"> file</span><span style="color:#7F848E;font-style:italic;">      # 截断超过 80 字符的行</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_8-5-日志处理" tabindex="-1"><a class="header-anchor" href="#_8-5-日志处理"><span>8.5 日志处理</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 案例1：提取指定时间段日志</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#D19A66;"> -n</span><span style="color:#98C379;"> &#39;/2024-01-15 09:00/,/2024-01-15 17:00/p&#39;</span><span style="color:#98C379;"> app.log</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 案例2：去除日志中的调试信息</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;/DEBUG/d&#39;</span><span style="color:#98C379;"> app.log</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 案例3：格式化日志时间戳</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#D19A66;"> -E</span><span style="color:#98C379;"> &#39;s/([0-9]{4})([0-9]{2})([0-9]{2})/\\1-\\2-\\3/g&#39;</span><span style="color:#98C379;"> app.log</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 20240115 → 2024-01-15</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 案例4：在异常信息后添加分隔线</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;/Exception/a\\================================&#39;</span><span style="color:#98C379;"> app.log</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 案例5：压缩多行堆栈为单行</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;:a;/Exception/{N;s/\\n/ | /;ba;}&#39;</span><span style="color:#98C379;"> app.log</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 案例6：日志脱敏（隐藏手机号中间4位）</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#D19A66;"> -E</span><span style="color:#98C379;"> &#39;s/(1[3-9][0-9])[0-9]{4}([0-9]{4})/\\1****\\2/g&#39;</span><span style="color:#98C379;"> user.log</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 13812345678 → 138****5678</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_9-gnu-sed-扩展特性" tabindex="-1"><a class="header-anchor" href="#_9-gnu-sed-扩展特性"><span>9. GNU sed 扩展特性</span></a></h2><h3 id="_9-1-扩展正则-e" tabindex="-1"><a class="header-anchor" href="#_9-1-扩展正则-e"><span>9.1 扩展正则 -E</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 使用扩展正则（减少反斜杠）</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#D19A66;"> -E</span><span style="color:#98C379;"> &#39;s/([0-9]{1,3}\\.){3}[0-9]{1,3}/[IP REDACTED]/g&#39;</span><span style="color:#98C379;"> access.log</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 不用 -E 的等价写法（满眼反斜杠）</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;s/\\([0-9]\\{1,3\\}\\.\\)\\{3\\}[0-9]\\{1,3\\}/[IP REDACTED]/g&#39;</span><span style="color:#98C379;"> access.log</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_9-2-特殊转义序列" tabindex="-1"><a class="header-anchor" href="#_9-2-特殊转义序列"><span>9.2 特殊转义序列</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># \\L \\U \\l \\u ——大小写转换</span></span>
<span class="line"><span style="color:#56B6C2;">echo</span><span style="color:#98C379;"> &#39;hello WORLD&#39;</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;s/.*/\\U&amp;/&#39;</span><span style="color:#7F848E;font-style:italic;">          # HELLO WORLD</span></span>
<span class="line"><span style="color:#56B6C2;">echo</span><span style="color:#98C379;"> &#39;hello WORLD&#39;</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;s/.*/\\L&amp;/&#39;</span><span style="color:#7F848E;font-style:italic;">          # hello world</span></span>
<span class="line"><span style="color:#56B6C2;">echo</span><span style="color:#98C379;"> &#39;hello world&#39;</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;s/\\w\\+/\\u&amp;/&#39;</span><span style="color:#7F848E;font-style:italic;">        # Hello world（首单词首字母大写）</span></span>
<span class="line"><span style="color:#56B6C2;">echo</span><span style="color:#98C379;"> &#39;hello world&#39;</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;s/\\b\\w/\\u&amp;/g&#39;</span><span style="color:#7F848E;font-style:italic;">       # Hello World（每个单词首字母大写）</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># \\n ——换行符</span></span>
<span class="line"><span style="color:#56B6C2;">echo</span><span style="color:#98C379;"> &#39;abc&#39;</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;s/b/\\n/&#39;</span><span style="color:#7F848E;font-style:italic;">                     # a\\nc（在替换中插入换行）</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># \\t ——制表符</span></span>
<span class="line"><span style="color:#56B6C2;">echo</span><span style="color:#98C379;"> &#39;a,b,c&#39;</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;s/,/\\t/g&#39;</span><span style="color:#7F848E;font-style:italic;">                 # a	b	c</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_9-3-特殊地址" tabindex="-1"><a class="header-anchor" href="#_9-3-特殊地址"><span>9.3 特殊地址</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 0,addr ——从文件开头匹配（GNU 扩展）</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 标准 sed 中 1,/pat/ 不会匹配第1行本身就包含 pat 的情况</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 0,/pat/ 可以正确处理</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#D19A66;"> -n</span><span style="color:#98C379;"> &#39;0,/^START/p&#39;</span><span style="color:#98C379;"> file</span><span style="color:#7F848E;font-style:italic;">       # 从开头到第一个 START</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># +N ——匹配地址后 N 行</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#D19A66;"> -n</span><span style="color:#98C379;"> &#39;/pattern/,+3p&#39;</span><span style="color:#98C379;"> file</span><span style="color:#7F848E;font-style:italic;">     # 匹配行及其后 3 行</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># ~N ——步长</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#D19A66;"> -n</span><span style="color:#98C379;"> &#39;1~3p&#39;</span><span style="color:#98C379;"> file</span><span style="color:#7F848E;font-style:italic;">              # 第1、4、7、10...行</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_10-sed-性能与技巧" tabindex="-1"><a class="header-anchor" href="#_10-sed-性能与技巧"><span>10. sed 性能与技巧</span></a></h2><h3 id="_10-1-性能优化" tabindex="-1"><a class="header-anchor" href="#_10-1-性能优化"><span>10.1 性能优化</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 1. 用 q 提前退出（找到即停）</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;/pattern/{p;q;}&#39;</span><span style="color:#98C379;"> file</span><span style="color:#7F848E;font-style:italic;">      # 找到第一个匹配即退出</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 2. 用地址范围减少处理行数</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#D19A66;"> -n</span><span style="color:#98C379;"> &#39;1000,2000s/old/new/p&#39;</span><span style="color:#98C379;"> file</span><span style="color:#7F848E;font-style:italic;">   # 只处理 1000-2000 行</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 3. 多个替换合并</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 慢：多次调用</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;s/a/A/g&#39;</span><span style="color:#98C379;"> file</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;s/b/B/g&#39;</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;s/c/C/g&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 快：一次调用</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;s/a/A/g; s/b/B/g; s/c/C/g&#39;</span><span style="color:#98C379;"> file</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 4. LC_ALL=C 加速</span></span>
<span class="line"><span style="color:#E06C75;">LC_ALL</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;">C</span><span style="color:#61AFEF;"> sed</span><span style="color:#98C379;"> &#39;s/pattern/replacement/g&#39;</span><span style="color:#98C379;"> large_file</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_10-2-调试技巧" tabindex="-1"><a class="header-anchor" href="#_10-2-调试技巧"><span>10.2 调试技巧</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 使用 l 命令查看模式空间（不可见字符可视化）</span></span>
<span class="line"><span style="color:#56B6C2;">echo</span><span style="color:#D19A66;"> -e</span><span style="color:#98C379;"> &#39;hello\\tworld&#39;</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">sed</span><span style="color:#D19A66;"> -n</span><span style="color:#98C379;"> &#39;l&#39;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># hello\\tworld$    （Tab 和行尾 $ 可见）</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 使用 = 查看行号</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#D19A66;"> -n</span><span style="color:#98C379;"> &#39;=;p&#39;</span><span style="color:#98C379;"> file</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;N;s/\\n/: /&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 逐步调试（打印每步处理后的模式空间）</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;s/a/A/;l;s/b/B/;l&#39;</span><span style="color:#98C379;"> file</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_10-3-常见错误" tabindex="-1"><a class="header-anchor" href="#_10-3-常见错误"><span>10.3 常见错误</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 错误1：忘记 -n 导致输出翻倍</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;p&#39;</span><span style="color:#98C379;"> file</span><span style="color:#7F848E;font-style:italic;">          # 每行打印两遍（自动输出 + p 打印）</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#D19A66;"> -n</span><span style="color:#98C379;"> &#39;p&#39;</span><span style="color:#98C379;"> file</span><span style="color:#7F848E;font-style:italic;">       # 正确</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 错误2：-i 和管道冲突</span></span>
<span class="line"><span style="color:#61AFEF;">cat</span><span style="color:#98C379;"> file</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">sed</span><span style="color:#D19A66;"> -i</span><span style="color:#98C379;"> &#39;s/old/new/&#39;</span><span style="color:#7F848E;font-style:italic;">    # 错误！-i 只能用于文件</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;s/old/new/&#39;</span><span style="color:#98C379;"> file</span><span style="color:#ABB2BF;"> &gt; </span><span style="color:#98C379;">output</span><span style="color:#7F848E;font-style:italic;">    # 正确</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 错误3：macOS sed 和 GNU sed 差异</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># macOS sed 不支持 -i 不带参数</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#D19A66;"> -i</span><span style="color:#98C379;"> &#39;s/old/new/&#39;</span><span style="color:#98C379;"> file</span><span style="color:#7F848E;font-style:italic;">          # macOS 报错</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#D19A66;"> -i</span><span style="color:#98C379;"> &#39;&#39;</span><span style="color:#98C379;"> &#39;s/old/new/&#39;</span><span style="color:#98C379;"> file</span><span style="color:#7F848E;font-style:italic;">       # macOS 写法</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 建议安装 gsed</span></span>
<span class="line"><span style="color:#61AFEF;">brew</span><span style="color:#98C379;"> install</span><span style="color:#98C379;"> gnu-sed</span></span>
<span class="line"><span style="color:#61AFEF;">gsed</span><span style="color:#D19A66;"> -i</span><span style="color:#98C379;"> &#39;s/old/new/&#39;</span><span style="color:#98C379;"> file</span><span style="color:#7F848E;font-style:italic;">         # GNU sed 写法</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container warning"><p class="hint-container-title">macOS sed 兼容性</p><p>macOS 自带的 sed 是 BSD 版本，与 GNU sed 有多处不兼容：</p><ol><li><code>-i</code> 必须带参数（空字符串 <code>&#39;&#39;</code> 表示无备份）</li><li>不支持 <code>-E</code> 以外的 GNU 扩展</li><li>转义序列行为不同（<code>\\t</code>、<code>\\n</code> 等）</li><li>建议在 macOS 上安装 <code>gnu-sed</code>：<code>brew install gnu-sed</code></li></ol></div><h2 id="_11-sed-与其他工具对比" tabindex="-1"><a class="header-anchor" href="#_11-sed-与其他工具对比"><span>11. sed 与其他工具对比</span></a></h2><h3 id="_11-1-sed-vs-tr" tabindex="-1"><a class="header-anchor" href="#_11-1-sed-vs-tr"><span>11.1 sed vs tr</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 简单字符转换 → 用 tr</span></span>
<span class="line"><span style="color:#56B6C2;">echo</span><span style="color:#98C379;"> &#39;hello&#39;</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">tr</span><span style="color:#98C379;"> &#39;a-z&#39;</span><span style="color:#98C379;"> &#39;A-Z&#39;</span><span style="color:#7F848E;font-style:italic;">        # HELLO（更快更简洁）</span></span>
<span class="line"><span style="color:#56B6C2;">echo</span><span style="color:#98C379;"> &#39;hello&#39;</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;s/.*/\\U&amp;/&#39;</span><span style="color:#7F848E;font-style:italic;">       # HELLO（大材小用）</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 删除字符 → 用 tr</span></span>
<span class="line"><span style="color:#56B6C2;">echo</span><span style="color:#98C379;"> &#39;hello 123&#39;</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">tr</span><span style="color:#D19A66;"> -d</span><span style="color:#98C379;"> &#39;0-9&#39;</span><span style="color:#7F848E;font-style:italic;">       # hello</span></span>
<span class="line"><span style="color:#56B6C2;">echo</span><span style="color:#98C379;"> &#39;hello 123&#39;</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;s/[0-9]//g&#39;</span><span style="color:#7F848E;font-style:italic;">  # hello</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 压缩重复字符 → 用 tr</span></span>
<span class="line"><span style="color:#56B6C2;">echo</span><span style="color:#98C379;"> &#39;heeellooo&#39;</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">tr</span><span style="color:#D19A66;"> -s</span><span style="color:#98C379;"> &#39;elo&#39;</span><span style="color:#7F848E;font-style:italic;">       # helo</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_11-2-sed-vs-awk" tabindex="-1"><a class="header-anchor" href="#_11-2-sed-vs-awk"><span>11.2 sed vs awk</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 简单替换 → 用 sed</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;s/old/new/g&#39;</span><span style="color:#98C379;"> file</span><span style="color:#7F848E;font-style:italic;">               # 更简洁</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 涉及字段计算 → 用 awk</span></span>
<span class="line"><span style="color:#61AFEF;">awk</span><span style="color:#98C379;"> &#39;{sum += $3} END {print sum}&#39;</span><span style="color:#7F848E;font-style:italic;">    # sed 无法做算术</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 条件替换 → 视复杂度选择</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#98C379;"> &#39;/pattern/s/old/new/&#39;</span><span style="color:#98C379;"> file</span><span style="color:#7F848E;font-style:italic;">       # 简单条件用 sed</span></span>
<span class="line"><span style="color:#61AFEF;">awk</span><span style="color:#98C379;"> &#39;/pattern/{gsub(/old/, &quot;new&quot;); print}&#39;</span><span style="color:#98C379;"> file</span><span style="color:#7F848E;font-style:italic;">  # 复杂条件用 awk</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_11-3-适用场景总结" tabindex="-1"><a class="header-anchor" href="#_11-3-适用场景总结"><span>11.3 适用场景总结</span></a></h3><table><thead><tr><th>场景</th><th>推荐工具</th><th>原因</th></tr></thead><tbody><tr><td>简单替换</td><td>sed</td><td>语法简洁，速度快</td></tr><tr><td>字符转换</td><td>tr</td><td>专为此设计</td></tr><tr><td>字段处理</td><td>awk</td><td>原生字段分割</td></tr><tr><td>配置修改</td><td>sed</td><td><code>-i</code> 就地修改</td></tr><tr><td>删除/过滤行</td><td>sed/grep</td><td>两者皆可</td></tr><tr><td>计算统计</td><td>awk</td><td>支持算术运算</td></tr><tr><td>格式转换</td><td>sed</td><td>灵活的正则替换</td></tr></tbody></table><h2 id="小结" tabindex="-1"><a class="header-anchor" href="#小结"><span>小结</span></a></h2>`,50),r(p,{code:``}),c[5]||=a(`blockquote`,null,[a(`p`,null,[a(`strong`,null,`参考书目`)]),a(`ul`,null,[a(`li`,null,`《sed & awk 101 Hacks》—— Ramesh Natarajan`),a(`li`,null,`《AWK程序设计语言》—— Alfred V. Aho, Brian W. Kernighan, Peter J. Weinberger`),a(`li`,null,`《Linux命令行与Shell脚本编程大全》（第4版）—— Richard Blum, Christine Bresnahan`),a(`li`,null,[i(`GNU sed 官方手册：`),a(`a`,{href:`https://www.gnu.org/software/sed/manual/`,target:`_blank`,rel:`noopener noreferrer`},`https://www.gnu.org/software/sed/manual/`)])])],-1)])}var d=s(l,[[`render`,u]]);export{c as _pageData,d as default};